WITH ended_lessons AS (SELECT school_uid,course_id,class_id FROM eo_pdviews.ods_ms_eo_os_eeo_course_class_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND class_btime>=1788537600 AND class_btime<1789142400 AND class_status=3 AND school_uid>0 GROUP BY school_uid,course_id,class_id),
course_frame AS (SELECT a.school_uid,a.course_id,a.category_id,COUNT(DISTINCT l.class_id) AS opened_n FROM eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a JOIN ended_lessons l ON a.school_uid=l.school_uid AND a.course_id=l.course_id AND a.biz_id=l.class_id WHERE a.dt='2026-09-11' AND a.biz_type=1 AND a.is_deleted=0 AND a.publish_flag=2 AND a.category_id>0 AND a.start_time>=1788537600 AND a.start_time<1789142400 GROUP BY a.school_uid,a.course_id,a.category_id), pe AS (SELECT school_uid,course_id,category_id,activity_id,biz_type,action,uid,COUNT(1) AS n FROM eo_pdviews.dwd_acitive_user_lms_action_details_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND event_time>=1788537600 AND event_time<1789142400 AND role='student' AND biz_type IN (4) AND action IN ('handin_homework','handin_exam','looked_activity','join_discuss','readover_homework_st','readover_exam_st') GROUP BY school_uid,course_id,category_id,activity_id,biz_type,action,uid) SELECT e.biz_type,e.action,SUM(e.n) AS event_n,COUNT(1) AS student_activity_n,COUNT(DISTINCT e.uid) AS student_n,COUNT(DISTINCT e.activity_id) AS activity_n,COUNT(DISTINCT e.school_uid) AS school_n FROM pe e JOIN course_frame f ON e.school_uid=f.school_uid AND e.course_id=f.course_id AND e.category_id=f.category_id JOIN eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a ON a.id=e.activity_id AND a.school_uid=e.school_uid AND a.course_id=e.course_id AND a.category_id=e.category_id WHERE a.dt='2026-09-11' AND a.publish_flag=2 AND a.is_deleted=0 AND a.biz_type IN (4) AND a.start_time<1789142400 GROUP BY e.biz_type,e.action ORDER BY e.biz_type,e.action LIMIT 30
